import { LoginService } from './../login/login.service';
import { Component, OnInit } from '@angular/core';
import { SallesService } from './salles.service';

export interface Produto {
  id: number;
  nome: string;
  itens: string;
  preco: number;
  imagemUrl: string;
  quantidade: number;
  categoriaId: number;
}

@Component({
  selector: 'app-salles',
  templateUrl: './salles.component.html',
  styleUrls: ['./salles.component.css'],
})
export class SallesComponent implements OnInit {
  quantidadePedidos: number = 0;
  carPreenchido: boolean = true;
  quantidade: number = 0;
  mostrarSacola: boolean = false;
  itensNaSacola: Produto[] = [];
  categorias: any[] = [];
  produtos: Produto[] = [];
  termoDeBusca: string = '';
  isLoggedIn: boolean = false;
  constructor(private sallesService: SallesService, private loginService: LoginService) {
    this.isLoggedIn = this.loginService.isUserLoggedIn();
  }

  ngOnInit() {
    this.sallesService.getCategories().subscribe((categoriesData: any) => {
      this.categorias = categoriesData.result.map((categoria: any) => ({
        id: categoria.id,
        nome: categoria.name,
        produtos: [],
      }));

      this.sallesService.getProducts().subscribe((productsData: any) => {

        this.produtos = productsData.result
          .filter((produto: any) => produto.isEnabled)  
          .map((produto: any) => ({
            id: produto.id,
            nome: produto.name,
            preco: parseFloat(produto.price),
            itens: produto.items,
            description: produto.description,
            imagemUrl: produto.imageUrl,
            quantidade: 0,
            categoriaId: produto.categoriaId || null,
          }));

        this.associarProdutosComCategorias();
      });
    });

    console.log('product', this.produtos);
  }

  associarProdutosComCategorias() {
    this.categorias.forEach((categoria) => {
      categoria.produtos = this.produtos.filter(
        (produto: Produto) => produto.categoriaId === categoria.id
      );
    });
  }

  adicionarAoCarrinho(produto: Produto) {
    produto.quantidade++;
    this.itensNaSacola.push(produto);
    this.quantidadePedidos++;
  }

  removerDoCarrinho(produto: Produto) {
    if (produto.quantidade > 0) {
      produto.quantidade--;
      const index = this.itensNaSacola.indexOf(produto);
      if (index !== -1) {
        this.itensNaSacola.splice(index, 1);
      }
      this.quantidadePedidos--;
      this.carPreenchido = this.itensNaSacola.length > 0;
    }
  }

  limparSacola() {
    this.limparProdutos();
    this.itensNaSacola = [];
    this.quantidadePedidos = 0;
  }

  limparProdutos() {
    this.categorias.forEach((categoria) => {
      categoria.produtos.forEach((produto: Produto) => {
        produto.quantidade = 0;
      });
    });
  }

  toggleSacola() {
    this.mostrarSacola = !this.mostrarSacola;
  }

  fecharModal() {
    this.mostrarSacola = false;
  }

  buscarProduto() {
    const termo = this.termoDeBusca.toLowerCase();
    this.categorias.forEach((categoria) => {
      categoria.produtos = this.produtos.filter(
        (produto: Produto) =>
          produto.categoriaId === categoria.id &&
          produto.nome.toLowerCase().includes(termo)
      );
    });
  }
}
<app-top-bar></app-top-bar>

<div class="container">
  <div class="pedido">
    <h2>Categorias</h2>
    <ul class="categorias">
      <li *ngFor="let categoria of categorias">
        <a [href]="'#' + categoria.id">{{ categoria.nome }}</a>
      </li>
    </ul>
    <div class="busca">
      <input
        type="text"
        placeholder="Buscar produto"
        [(ngModel)]="termoDeBusca"
        (input)="buscarProduto()"
      />
      <button (click)="buscarProduto()">Buscar</button>
    </div>
    <ng-container *ngFor="let categoria of categorias">
      <section [id]="categoria.id">
        <h3>{{ categoria.nome }}</h3>
        <div class="produtos">
          <div class="produto" *ngFor="let produto of categoria.produtos">
            <img
              class="product-img"
              [src]="produto.imagemUrl"
              [alt]="produto.nome"
            />
            <h4>{{ produto.nome }}</h4>
            <p>Itens: {{ produto.itens }}</p>
            <p>Descrição: {{ produto.description }}</p>
            <p>Preço: R$ {{ produto.preco.toFixed(2) }}</p>
            <div class="botoes">
              <button class="adicionar" (click)="adicionarAoCarrinho(produto)">
                Adicionar
              </button>
              <span class="quantidade">{{ produto.quantidade }}</span>
              <button class="remover" (click)="removerDoCarrinho(produto)">
                Remover
              </button>
            </div>
          </div>
        </div>
      </section>
    </ng-container>
  </div>
  <div>
    <div
      *ngIf="quantidadePedidos > 0"
      class="carrinho"
      (click)="toggleSacola()"
    >
      <img class="w-icone" src="assets/icone/car.gif" style="cursor: pointer" />
      <span class="quantidade-carrinho">{{ quantidadePedidos }}</span>
    </div>
    <app-app-sacola
      [itensNaSacola]="itensNaSacola"
      [modalAberto]="mostrarSacola"
      *ngIf="mostrarSacola"
      (fecharModals)="fecharModal()"
      (limparProdutosSalles)="limparSacola()"
    >
    </app-app-sacola>
  </div>
</div>
